# Generated by manage.py generate_test_cases.
from bs4 import BeautifulSoup

from bloomerp.widgets.foreign_field_widget import ForeignFieldWidget
from bloomerp.tests.base import BloomerpWidgetTestCase, WidgetOperation, WidgetScenario


class TestForeignFieldWidget(BloomerpWidgetTestCase[ForeignFieldWidget]):
    widget_class = ForeignFieldWidget

    def get_test_scenarios(self) -> list[WidgetScenario[ForeignFieldWidget]]:
        """Cover inline token markup for both relationship cardinalities."""
        return [
            WidgetScenario(
                name=f"{'multiple' if is_m2m else 'single'} selections share the input control",
                constructor_kwargs={"attrs": {"is_m2m": is_m2m}},
                operations=[
                    WidgetOperation(
                        name="render inline relationship control",
                        execute=self.render_relationship,
                        result_validators=self.has_inline_selection_control,
                    ),
                ],
            )
            for is_m2m in (False, True)
        ]

    def render_relationship(self, widget: ForeignFieldWidget) -> str:
        """Render selected identifiers without requiring database lookups."""
        return widget.render("owner", ["3", "7"] if widget.is_m2m else "3")

    def has_inline_selection_control(self, html: str) -> bool:
        """Require tokens and the empty search input inside one bordered control."""
        markup = BeautifulSoup(html, "html.parser")
        control = markup.select_one(".foreign-field-control")
        self.assertIsNotNone(control)
        self.assertIsNotNone(control.select_one(".foreign-field-selected"))
        search = control.select_one('input[type="text"]')
        self.assertIsNotNone(search)
        self.assertEqual(search.get("value", ""), "")
        self.assertIsNone(search.get("name"))
        self.assertEqual(len(markup.select(".foreign-field-selected")), 1)
        return True
